from datetime import date

class Book:
    def __init__(self, isbn, title):
        self.isbn = isbn
        self.title = title
        self.available = True

class Loan:
    def __init__(self, book, reader_id, borrow_date):
        self.book = book
        self.reader_id = reader_id
        self.borrow_date = borrow_date
        self.returned = False

class Library:
    def __init__(self):
        self.books = {}
        self.loans = []

    def borrow_book(self, isbn, reader_id, today):
        book = self.books[isbn]
        if not book.available:
            raise ValueError('已被借出')
        book.available = False
        self.loans.append(Loan(book, reader_id, today))

    def return_book(self, isbn, today):
        for loan in reversed(self.loans):
            if loan.book.isbn == isbn and not loan.returned:
                loan.returned = True
                loan.book.available = True
                return loan
        raise ValueError('该书没有未归还记录')

lib = Library()
lib.books['A1'] = Book('A1', '算法图解')
lib.borrow_book('A1', 'R1', date(2026, 3, 1))
print('借出后可借：', lib.books['A1'].available)
loan = lib.return_book('A1', date(2026, 3, 20))
print('归还记录已归还：', loan.returned)
print('归还后可借：', lib.books['A1'].available)
